entries[129176] = { ["name"] = "Schattenwort: Tod", ["text"] = "2.6% von Grundmana 40 Meter Reichweite\nSofort 8 sek. Abklingzeit\nEin Wort der bindenden Dunkelheit, das sowohl dem Ziel als auch dem Zaubernden 627 Schattenschaden zufügt.\n\nWenn das Ziel über weniger als 20% Gesundheit verfügt, erleidet es das Vierfache des Schadens und die Abklingzeit des Zaubers wird zurückgesetzt. Diese Zurücksetzung kann nur einmal alle 9 Sek. auftreten. [ Gedankenschinden : Gewährt Euch eine Schattenkugel, wenn das Ziel weniger als 20% Gesundheit hat ]\nWenn der Zauber das Ziel tötet, erleidet Ihr keinen Schaden [ Gedankenschinden : und erhaltet eine zusätzliche Schattenkugel, wenn die Abklingzeit von 'Schattenwort: Tod' in den letzten 6 Sek. nicht abgeschlossen wurde ]." }
entries[129178] = { ["name"] = "Sha-Kugel", ["text"] = "Unbegrenzte Reichweite\nSofort\nKugeln aus Sha-Energie werden aus dem verderbten Wächter geschlagen, wenn er Gesundheit verliert. Bei Berührung wird die Kugel aufgezehrt, wobei sie 46800 Schattenschaden verursacht, aber mit der Zeit die Primärressource des Spielercharakters wieder auffüllt. Wenn die Kugel nicht innerhalb von 8 Sek. verbraucht wird, kehrt sie zum Wächter zurück und heilt ihn um 8% seiner maximalen Gesundheit." }
