entries[129410] = { ["name"] = "Tödliches Gift", ["text"] = "Wirken in 3 sek.\nBenötigt Einhändige Nahkampfwaffe\nÜberzieht Eure Waffen mit einem tödlichen Gift , das 1 Stunde lang an ihnen haften bleibt. Bei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften. Das Gift verursacht im Verlauf von 12 Sek. ( 748 * 4) Naturschaden. Weitere Anwendungen auf das Ziel während der Effektdauer verursachen sofort 390 Naturschaden.\n(Procchance: 30%)" }
entries[129411] = { ["name"] = "Totem der Erdbindung", ["text"] = "30 Mana\nSofort\nTools: Erdtotem\nBeschwört ein Totem der Erdbindung, das 45 Sek. lang bestehen bleibt und in regelmäßigen Abständen das Bewegungstempo von in der Nähe befindlichen Feinden auf 50% des normalen Tempos verringert." }
entries[129412] = { ["name"] = "Wundgift", ["text"] = "Wirken in 3 sek.\nBenötigt Einhändige Nahkampfwaffe\nÜberzieht Eure Waffen mit einem tödlichen Gift, das 1 Stunde lang an ihnen haften bleibt. Bei jedem Angriff besteht eine Chance von 30%, den Gegner zu vergiften, was sofort 520 Naturschaden verursacht sowie 15 Sek. lang die erhaltene Heilung verringert.\n(Procchance: 30%)" }
entries[129413] = { ["name"] = "Gedankenbenebelndes Gift", ["text"] = "Wirken in 3 sek.\nBenötigt Einhändige Nahkampfwaffe\nÜberzieht Eure Waffen mit einem nicht-tödlichen Gift , das 1 Stunde lang an ihnen haften bleibt. Bei jedem Schlag besteht eine Chance von 50%, den Gegner zu vergiften. Das Gift vernebelt die Gedanken des Betroffenen und verringert so sein Zaubertempo 10 Sek. lang um 50% (25% bei Spielercharakteren). [ Tückische Klinge : Effekt von 'Tückische Klinge':\nErhöht die Zauberzeit des nächsten innerhalb von 8 Sek. gewirkten Zaubers des Ziels um 100% ](Procchance: 50%)" }
